"""Render exact registered results, without performance-based parameter changes."""
import json,hashlib,platform,sys
import numpy as np,pandas as pd,sklearn,scipy,lightgbm
from data27 import R,P,R26,SYMS
from run27 import VARIANTS
NAMES={'mean_payoff_price':'Probabilidade + ganhos/perdas médios','magnitude_price':'Ganho/perda previstos','duration_price':'Ganho/perda + duração','duration_book':'Ganho/perda + duração + book','direct_book':'Retorno direto + duração + book','conservative_book':'Retorno direto com penalização','duration_book_no_adaptive':'Ganho/perda + duração + book, sem pausas','rule_momentum':'Momentum determinístico','reference':'Referência de impulso de volume','duration_book_h30':'Modelo com book: somente 30 min','duration_book_h60':'Modelo com book: somente 60 min','duration_book_h180':'Modelo com book: somente 180 min'}
def pct(x):return f'{100*x:+.3f}%'
def num(x):return '—' if x is None else f'{x:.3f}'
def main():
 s=json.loads((R/'results/summary.json').read_text());c=s['combined'];verification=json.loads((R/'VERIFICATION.json').read_text())
 (R/'COMPARISON.json').write_text(json.dumps(c,indent=2)+'\n')
 diag={m:d['diagnostics'] for m,d in s['models'].items()};(R/'FORECAST_DIAGNOSTICS.json').write_text(json.dumps(diag,indent=2)+'\n')
 lines=['# R17.27 — resultado dos testes de magnitude e duração','', '**Concluído em 26/11/2026.** Pesquisa isolada na branch `research-r17-27-magnitude-duration`. Objetivo: verificar se estimar ganho, perda e duração e aumentar os horizontes supera a R17.26. Meta de 5% a 10% ao mês é apenas critério de pesquisa.','',f"**Seleção congelada antes do replay de novembro: CAIXA. Critério histórico de meta aprovado: não. Nenhuma alteração promovida à versão principal.**",'', '## Comparação líquida: julho a outubro de 2026','', 'Retorno total compreende 123 dias. Mensal equivalente usa `(1+retorno_total)^(30,4375/dias)-1`; não significa que cada mês rendeu esse valor. Taxas, spread, slippage e funding estão incluídos. Caixa não negocia, portanto não demonstra vantagem preditiva.','', '| Variante | Total líquido | Mensal equivalente | DD máximo | Sharpe | Profit factor | Trades | Meses positivos | Total com custos 2x |','|---|---:|---:|---:|---:|---:|---:|---:|---:|']
 for v in VARIANTS:
  a=c[f'walk_forward_{v}_cost1'];b=c[f'walk_forward_{v}_cost2'];lines.append(f"| {NAMES[v]} | {pct(a['total_return'])} | {pct(a['monthly_equivalent'])} | {100*a['max_drawdown']:.3f}% | {num(a['sharpe'])} | {num(a['profit_factor'])} | {a['trades']} | {a['positive_folds']}/4 | {pct(b['total_return'])} |")
 lines+=['','## Retornos mensais efetivamente observados','', '**Novembro cobre apenas 1 a 24/11/2026 (UTC).** Nenhum resultado do restante de novembro ou de dezembro foi observado. Os demais meses de 2026 não fazem parte desta avaliação; dezembro/2025 a junho/2026 fornecem histórico e treino.','', '| Variante | Julho | Agosto | Setembro | Outubro | Novembro parcial | Nov. custos 2x |','|---|---:|---:|---:|---:|---:|---:|']
 for v in VARIANTS:
  vals=[s['results'][f'{m}_{v}_cost1']['total_return'] for m in P['walk_forward_months']+['2026-11']];lines.append('| '+NAMES[v]+' | '+' | '.join(pct(x) for x in vals)+' | '+pct(c[f'final_{v}_cost2']['total_return'])+' |')
 lines+=['','## O que cada mudança entregou','', 'As diferenças abaixo usam os mesmos dados, limites de risco e custos entre os componentes, salvo a retirada explícita das pausas. Modelos sem book e com book usam as mesmas linhas válidas de book, inclusive no treino; assim a diferença não vem de negociar em calendários diferentes. Os intervalos são bootstrap pareado de blocos de sete dias, 500 trajetórias; são descritivos e não corrigem seleção entre modelos ou reutilização do histórico.','', '| Componente acrescentado | Diferença de retorno total (p.p.) | Intervalo descritivo de 95% (p.p.) |','|---|---:|---:|']
 for a in s['paired_bootstrap']:
  delta=c[f"walk_forward_{a['left']}_cost1"]['total_return']-c[f"walk_forward_{a['right']}_cost1"]['total_return'];lo,hi=a['total_return_difference_95_interval'];lines.append(f"| {NAMES[a['left']]} versus {NAMES[a['right']]} | {100*delta:+.3f} | [{100*lo:+.3f}; {100*hi:+.3f}] |")
 lines+=['','## Qualidade preditiva fora do treino','', 'RMSE de retorno é medido em R bruto por oportunidade, antes dos custos. A referência constante é estimada apenas no mês de calibração. Ganhar em RMSE médio não prova rentabilidade nas poucas oportunidades escolhidas. Duração compara MAE em minutos com duração constante da calibração.','', '| Janela | Horizonte | Features | RMSE direto | RMSE constante | RMSE condicional | MAE duração | MAE constante | Brier | Brier constante |','|---|---:|---|---:|---:|---:|---:|---:|---:|---:|']
 for month,items in diag.items():
  for key,d in items.items():
   h,kind=key.split('_');lines.append(f"| {month} | {h} min | {kind} | {d['direct_rmse']:.4f} | {d['constant_mean_rmse']:.4f} | {d['conditional_rmse']:.4f} | {d['duration_mae']:.2f} | {d['constant_duration_mae']:.2f} | {d['brier']:.4f} | {d['prior_brier']:.4f} |")
 lines+=['','## Decomposição financeira (julho a outubro)','', 'Capital inicial de referência: 10.000 unidades de cotação. Agregados encadeados; PnL de preço já contém spread e slippage. Líquido = PnL de preço − taxas + funding. Valores em unidades de cotação.','', '| Variante | PnL preço após execução | Taxas | Funding | Líquido | Trades 30/60/180 min |','|---|---:|---:|---:|---:|---|']
 for v in VARIANTS:
  a=c[f'walk_forward_{v}_cost1'];hh=a['trades_by_horizon'];lines.append(f"| {NAMES[v]} | {a['price_pnl_after_spread_slippage']:.2f} | {a['fees']:.2f} | {a['funding']:.2f} | {a['total_return']*10000:.2f} | {hh['30']}/{hh['60']}/{hh['180']} |")
 lines+=['','## Diagnóstico direto e decisão','', '**Não chegamos perto de 5% a 10% ao mês. A maioria das alternativas perdeu dinheiro. Não recomendo incorporá-las ao robô principal.**','', '1. O horizonte isolado de 60 minutos foi o melhor indício: +1,292% em julho–outubro, equivalente a +0,318% ao mês, DD de 0,496% e PF de 2,925. Porém foram só 16 operações e apenas dois meses positivos. Em novembro parcial ganhou +0,043% com uma única operação. No cenário 2x, o filtro passa a aceitar apenas uma operação no período de desenvolvimento, que ganhou +0,050%; isso não é evidência robusta e tampouco é estresse da mesma lista fixa de trades. Não ampliar posição nem alavancagem com essa amostra.','2. Estimar ganho/perda reduziu o prejuízo de −9,875% para −6,771% no desenvolvimento. Dividir pela duração não mudou as operações nem o resultado nessa comparação. Acrescentar book melhorou para −6,058%, ainda ruim; os intervalos pareados dessas melhorias incluem zero.','3. A regressão direta piorou para −17,345% e −9,641% em novembro parcial. O erro médio de previsão de retorno é pior que o de uma média constante da calibração. Há falha de generalização e superestimação das oportunidades aceitas; aumentar árvores, operar mais ou alavancar não resolve essa evidência. A duração foi estimada melhor que a constante, mas isso não se converteu em lucro.','4. O horizonte de três horas respondeu por 191 das 196 operações do modelo combinado e perdeu −6,775% quando isolado. Esse resultado domina a combinação; 30 minutos teve só cinco trades no desenvolvimento. A prioridade de investigação futura é uma réplica independente do teste de 60 minutos, não promover retrospectivamente o melhor recorte.','5. O momentum determinístico perdeu −56,590% no agregado das quatro avaliações mensais e deve ser descartado nessa formulação. O risco corta perdas em cada janela, mas não cria vantagem. O agregado pode passar de 20% porque o estado de risco reinicia mensalmente; não é um circuit breaker contínuo de produção.','6. A penalização conservadora não aceitou nenhuma ordem. Retorno zero aqui significa abstenção, não desempenho de um robô lucrativo.','', '**O que incorporar agora:** somente infraestrutura de previsão de magnitudes/duração, diagnóstico por horizonte, verificação causal/contábil e relatórios como ferramentas de pesquisa isoladas. Nenhum sinal novo foi aprovado para produção. **Próxima hipótese justificável:** congelar a política de 60 minutos sem ajustes e medir novas oportunidades em dados ainda não consultados e paper contínuo com custos reais; exigir amostra bem maior e estabilidade antes de qualquer integração. Não existe resultado desta rodada que justifique prometer retorno exponencial.','']
 lines+=['','## Método e dados','', '- BTCUSDT, ETHUSDT e SOLUSDT em futuros USDT-M: 1.550.880 candles de um minuto entre 01/12/2025 e 24/11/2026. Book público real desde abril: 1.994.457 snapshots. 837 ZIPs oficiais com SHA256 verificado; três arquivos de book de 08/10/2026 indisponíveis. Fontes e hashes na R17.26 e em `INPUT_HASHES.json`.','- Trinta conjuntos horizonte/features, cada um com cinco modelos: classificador, ganho condicional, perda condicional, duração e retorno direto. Total de 150 modelos LightGBM, mais calibração sigmoide. 132 árvores por cabeça; hiperparâmetros fixados antes de conhecer estes resultados.','- Treino móvel de dois meses, calibração de um mês, teste no mês seguinte; expurgo de 181 minutos em ambas as fronteiras, todos os ativos/direções agrupados no tempo. Nenhuma feature usa preço após a decisão. Entradas com um minuto de atraso.','- Stop por ATR escalado à raiz do horizonte, limitado a 0,3%–2%; alvo 2R; encerramento em 30/60/180 minutos. Dimensionamento por risco de 0,25%, teto 20% por ativo, exposição bruta 60%, até três posições, sem alavancagem. Controle preserva limite original de 15%.','- Pausa após três perdas, redução de risco com DD de 8%, parada a 20% e perda diária de 4%. Os tetos são gatilhos; custos e gaps podem ultrapassá-los. O estado reinicia em cada avaliação mensal.','- Cenário normal por lado: taxa de 0,06%, meio spread de 0,02%, slippage de 0,04%; custo estimado de ida e volta 0,24%, além de funding. Estresse dobra taxa e fricção. Ordens são taker; lote, tick, valor mínimo e limite de 0,1% do volume do minuto anterior são aplicados.','- Seleção entre sete candidatos usa apenas julho–outubro: PF >1,2; pelo menos 100 operações; três meses positivos; DD ≤20%; retorno superior ao controle e positivo no estresse. Três testes de horizonte isolado e a regra de momentum são diagnósticos, excluídos da seleção.','', '## Limitações e interpretação','', '**Todo esse histórico já foi consultado na R17.26.** A validação é cronológica fora do treino de cada janela, mas retrospectiva e não independente da pesquisa. Novembro foi separado da seleção desta rodada, porém também era conhecido em pesquisa anterior. Não chame estes resultados de prova prospectiva.','', 'Spread/slippage são cenários; snapshots de book não reconstroem fila, latência real ou fills. Os filtros de execução são os atuais, não filtros históricos point-in-time. Funding utiliza preço de abertura como proxy de mark. O controle é o adaptador documentado da R17.26, sem alegar equivalência integral com a baseline de produção R16.24.2. O teste mensal liquida posições ao fim da janela e reinicia o risco; o encadeamento não representa execução contínua sem reinícios. Retornos não incluem impostos. Não houve execução com dinheiro real.','',f"## Verificação e artefatos\n\n{verification['unit_tests']} testes unitários passaram; {verification['accounting_replays']} replays reconciliados; {verification['scalar_label_checks']} labels confrontados com implementação escalar independente; três verificações causais em prefixes reais. Hashes dos cinco arquivos de modelos e previsões, expurgo temporal e drawdown conferidos por rotina independente, incluindo código MIT do Vibe-Trading.", '', '- `protocol.json`: regras pré-definidas; `results/selection_before_final.json`: seleção congelada.','- `COMPARISON.json`, `FORECAST_DIAGNOSTICS.json` e `VERIFICATION.json`: métricas e evidência legíveis por máquina.','- `R17_27_RESULTS.zip`: código, cinco conjuntos completos de modelos, relatórios e todas as operações/curvas.','- `README.md`: reprodução; scripts herdados e licenças permanecem intactos na R17.26.','']
 (R/'RESULTADO_PT.md').write_text('\n'.join(lines))
 (R/'ENVIRONMENT.json').write_text(json.dumps(dict(python=sys.version,numpy=np.__version__,pandas=pd.__version__,scikit_learn=sklearn.__version__,scipy=scipy.__version__,lightgbm=lightgbm.__version__,platform=platform.platform()),indent=2)+'\n')
 print('REPORT_WRITTEN')
if __name__=='__main__':main()
